-- this snippet was generated by ChatGPT
local M = {}

function M.paste_image()
  local note_dir = vim.fn.expand("%:p:h")
  if note_dir == "" then
    vim.notify("No file path for current buffer", vim.log.levels.ERROR)
    return
  end

  local image_dir = note_dir .. "/image"
  vim.fn.mkdir(image_dir, "p")

  local filename = os.date("%Y%m%d-%H%M%S") .. ".png"
  local linux_path = image_dir .. "/" .. filename

  local win_path = vim.fn.system({ "wslpath", "-w", linux_path }):gsub("%s+$", "")
  if win_path == "" then
    vim.notify("Failed to convert path with wslpath", vim.log.levels.ERROR)
    return
  end

  local ps_cmd = table.concat({
    "Add-Type -AssemblyName System.Windows.Forms;",
    "$img = [System.Windows.Forms.Clipboard]::GetImage();",
    "if ($null -eq $img) { throw 'No clipboard image' };",
    "$ms = New-Object System.IO.MemoryStream;",
    "try {",
    "  $img.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png);",
    "  [System.IO.File]::WriteAllBytes('" .. win_path .. "', $ms.ToArray())",
    "} finally {",
    "  $ms.Dispose();",
    "  $img.Dispose()",
    "}",
  }, " ")

  local result = vim.fn.system({ "powershell.exe", "-NoProfile", "-STA", "-Command", ps_cmd })
  local ok = (vim.v.shell_error == 0)

  if not ok then
    vim.notify("Failed to save image:\n" .. result, vim.log.levels.ERROR)
    return
  end

  local rel_path = "image/" .. filename
  local line = string.format("![%s](%s)", filename, rel_path)
  vim.api.nvim_put({ line }, "c", true, true)

  vim.notify("Image pasted: " .. rel_path, vim.log.levels.INFO)
end

return M
